uv run --no-project python - <<'PY'
import re, pathlib, collections

docs = pathlib.Path("docs")
files = {p: p.read_text() for p in docs.rglob("*.md")}

def slug(t):
    t = t.strip().lower()
    t = re.sub(r"[^\w\s-]", "", t)
    return re.sub(r"\s", "-", t)

anchors = {}
for p, txt in files.items():
    seen = collections.Counter()
    s = set()
    for m in re.finditer(r"^#{1,6}\s+(.*)$", txt, re.M):
        base = slug(m.group(1))
        n = seen[base]; seen[base] += 1
        s.add(base if n == 0 else f"{base}-{n}")
    anchors[p] = s
    dupes = [k for k, v in seen.items() if v > 1]
    if dupes and "package-sync" in p.name:
        print("DUPLICATE HEADING SLUGS", p, dupes)

bad = 0
for p, txt in files.items():
    for m in re.finditer(r"\]\(([^)\s]*?)#([^)\s]+)\)", txt):
        tgt, frag = m.group(1), m.group(2)
        target = p if not tgt else (p.parent / tgt).resolve()
        if not tgt:
            pass
        elif not target.exists():
            print("MISSING FILE", p, tgt); bad += 1; continue
        key = next((k for k in anchors if k.resolve() == pathlib.Path(target).resolve()), None)
        if key is None:
            continue
        if frag not in anchors[key]:
            print("BROKEN ANCHOR", p, "->", tgt + "#" + frag); bad += 1
print("broken anchors:", bad)

req = files[docs/"planning/package-sync-user-requirements.md"]
crit = files[docs/"planning/package-sync-conformance-criteria.md"]
defined = set(re.findall(r"^- \*\*(PKG-[A-Z0-9-]+)\*\*", crit, re.M))
table = crit.split("## Traceability")[1]
mapped = re.findall(r"`(PKG-[A-Z0-9-]+)`", table)
print("defined:", len(defined), "mapped:", len(mapped), "unique mapped:", len(set(mapped)))
print("phantom (mapped, not defined):", sorted(set(mapped) - defined))
print("dangling (defined, not mapped):", sorted(defined - set(mapped)))
counts = re.findall(r"\|\s*\[([^\]]+)\]\([^)]+\)\s*\|\s*(\d+)\s*\|([^|]*)\|", table)
for name, n, ids in counts:
    actual = len(re.findall(r"`PKG-", ids))
    if int(n) != actual:
        print("COUNT MISMATCH", name, n, "!=", actual)

banned = ["diff ", "direction", "travel", "vendor", "screen", "keystroke", " you ", " your "]
for w in banned:
    hits = [l for l in req.lower().splitlines() if w in l]
    if hits:
        print("BANNED", repr(w), len(hits), hits[:2])
